                <h1 id="moodle-student-dashboard">Moodle Student Dashboard</h1>

    <p>Read-only endpoints for a student viewing their own enrolled courses,
course details, and section content (materials + assignments).</p>
<p>--- ACCESS CONTROL ---
Every method here checks two things before returning data:</p>
<ol>
<li>The authenticated user has a <code>student</code> profile at all
(guarded here defensively — TODO: move to route middleware once written).</li>
<li>For course-scoped endpoints, that student is actually enrolled in
the requested course (via the <code>course_student</code> pivot), so a student
can never view another course's content by guessing its ID.</li>
</ol>
<p>--- RESOURCE USAGE NOTE ---
No new Resource classes were added for this feature. Where an existing
Resource already covers a shape (CourseResource, SectionItemResource,
SectionSubmissionResource), it's reused directly via -&gt;resolve(). Where
the student view needs extra fields those Resources don't provide
(teacher's flattened name/email, per-student submission status, the
student's own submitted file), that logic is written inline below
instead of creating another Resource file.</p>

